    50  static XY s_forward (LP lp, PJ *P) {           /* Spheroidal, forward */
    51      XY xy = {0.0,0.0};
    52      struct pj_opaque *Q = P->opaque;
    53      double Vx, Vy, Vz, tmp;
    54
    55      /* Calculation of the three components of the vector from satellite to
    56      ** position on earth surface (lon,lat).*/
    57      tmp = cos(lp.phi);
    58      Vx = cos (lp.lam) * tmp;
    59      Vy = sin (lp.lam) * tmp;
    60      Vz = sin (lp.phi);
    61
    62      /* Check visibility*/
    63
    64
    65      /* Calculation based on view angles from satellite.*/
    66      tmp = Q->radius_g - Vx;
    67
    68      if(Q->flip_axis) {
    69          xy.x = Q->radius_g_1 * atan(Vy / hypot(Vz, tmp));
    70          xy.y = Q->radius_g_1 * atan(Vz / tmp);
    71      } else {
    72          xy.x = Q->radius_g_1 * atan(Vy / tmp);
    73          xy.y = Q->radius_g_1 * atan(Vz / hypot(Vy, tmp));
    74      }
    75
    76      return xy;
    77  }
