    79
    80  static XY e_forward (LP lp, PJ *P) {          /* Ellipsoidal, forward */
    81      XY xy = {0.0,0.0};
    82      struct pj_opaque *Q = P->opaque;
    83      double r, Vx, Vy, Vz, tmp;
    84
    85      /* Calculation of geocentric latitude. */
    86      lp.phi = atan (Q->radius_p2 * tan (lp.phi));
    87
    88      /* Calculation of the three components of the vector from satellite to
    89      ** position on earth surface (lon,lat).*/
    90      r = (Q->radius_p) / hypot(Q->radius_p * cos (lp.phi), sin (lp.phi));
    91      Vx = r * cos (lp.lam) * cos (lp.phi);
    92      Vy = r * sin (lp.lam) * cos (lp.phi);
    93      Vz = r * sin (lp.phi);
    94
    95      /* Check visibility. */
    96      if (((Q->radius_g - Vx) * Vx - Vy * Vy - Vz * Vz * Q->radius_p_inv2) < 0.) {
    97          proj_errno_set(P, PJD_ERR_TOLERANCE_CONDITION);
    98          return xy;
    99      }
   100
   101      /* Calculation based on view angles from satellite. */
   102      tmp = Q->radius_g - Vx;
   103
   104      if(Q->flip_axis) {
   105          xy.x = Q->radius_g_1 * atan (Vy / hypot (Vz, tmp));
   106          xy.y = Q->radius_g_1 * atan (Vz / tmp);
   107      } else {
   108          xy.x = Q->radius_g_1 * atan (Vy / tmp);
   109          xy.y = Q->radius_g_1 * atan (Vz / hypot (Vy, tmp));
   110      }
   111
   112      return xy;
   113  }
