   116  static LP s_inverse (XY xy, PJ *P) {           /* Spheroidal, inverse */
   117      LP lp = {0.0,0.0};
   118      struct pj_opaque *Q = P->opaque;
   119      double Vx, Vy, Vz, a, b, det, k;
   120
   121      /* Setting three components of vector from satellite to position.*/
   122      Vx = -1.0;
   123      if(Q->flip_axis) {
   124          Vz = tan (xy.y / (Q->radius_g - 1.0));
   125          Vy = tan (xy.x / (Q->radius_g - 1.0)) * sqrt (1.0 + Vz * Vz);
   126      } else {
   127          Vy = tan (xy.x / (Q->radius_g - 1.0));
   128          Vz = tan (xy.y / (Q->radius_g - 1.0)) * sqrt (1.0 + Vy * Vy);
   129      }
   130
   131      /* Calculation of terms in cubic equation and determinant.*/
   132      a = Vy * Vy + Vz * Vz + Vx * Vx;
   133      b = 2 * Q->radius_g * Vx;
   134      if ((det = (b * b) - 4 * a * Q->C) < 0.) {
   135          proj_errno_set(P, PJD_ERR_TOLERANCE_CONDITION);
   136          return lp;
   137      }
   138
   139      /* Calculation of three components of vector from satellite to position.*/
   140      k  = (-b - sqrt(det)) / (2 * a);
   141      Vx = Q->radius_g + k * Vx;
   142      Vy *= k;
   143      Vz *= k;
   144
   145      /* Calculation of longitude and latitude.*/
   146      lp.lam = atan2 (Vy, Vx);
   147      lp.phi = atan (Vz * cos (lp.lam) / Vx);
   148
   149      return lp;
   150  }
