   152
   153  static LP e_inverse (XY xy, PJ *P) {          /* Ellipsoidal, inverse */
   154      LP lp = {0.0,0.0};
   155      struct pj_opaque *Q = P->opaque;
   156      double Vx, Vy, Vz, a, b, det, k;
   157
   158      /* Setting three components of vector from satellite to position.*/
   159      Vx = -1.0;
   160
   161      if(Q->flip_axis) {
   162          Vz = tan (xy.y / Q->radius_g_1);
   163          Vy = tan (xy.x / Q->radius_g_1) * hypot(1.0, Vz);
   164      } else {
   165          Vy = tan (xy.x / Q->radius_g_1);
   166          Vz = tan (xy.y / Q->radius_g_1) * hypot(1.0, Vy);
   167      }
   168
   169      /* Calculation of terms in cubic equation and determinant.*/
   170      a = Vz / Q->radius_p;
   171      a   = Vy * Vy + a * a + Vx * Vx;
   172      b   = 2 * Q->radius_g * Vx;
   173      if ((det = (b * b) - 4 * a * Q->C) < 0.) {
   174          proj_errno_set(P, PJD_ERR_TOLERANCE_CONDITION);
   175          return lp;
   176      }
   177
   178      /* Calculation of three components of vector from satellite to position.*/
   179      k  = (-b - sqrt(det)) / (2. * a);
   180      Vx = Q->radius_g + k * Vx;
   181      Vy *= k;
   182      Vz *= k;
   183
   184      /* Calculation of longitude and latitude.*/
   185      lp.lam = atan2 (Vy, Vx);
   186      lp.phi = atan (Vz * cos (lp.lam) / Vx);
   187      lp.phi = atan (Q->radius_p_inv2 * tan (lp.phi));
   188
   189      return lp;
   190  }
