    38  /* Maximum size of files using the "escape carriage return" feature */
    39  #define MAX_CR_ESCAPE 65537
    40  typedef struct {
    41      projCtx ctx;
    42      PAFile fid;
    43      char buffer[MAX_CR_ESCAPE];
    44      int buffer_filled;
    45      int at_eof;
    46  } pj_read_state;
    47
    48  /************************************************************************/
    49  /*                            fill_buffer()                             */
    50  /************************************************************************/
    51
    52  static const char *fill_buffer(pj_read_state *state, const char *last_char)
    53  {
    54      size_t bytes_read;
    55      size_t char_remaining, char_requested;
    56      char   *r, *w;
    57
    58  /* -------------------------------------------------------------------- */
    59  /*      Don't bother trying to read more if we are at eof, or if the    */
    60  /*      buffer is still over half full.                                 */
    61  /* -------------------------------------------------------------------- */
    62      if (last_char == NULL)
    63          last_char = state->buffer;
    64
    65      if (state->at_eof)
    66          return last_char;
    67
    68      char_remaining = state->buffer_filled - (last_char - state->buffer);
    69      if (char_remaining >= sizeof(state->buffer) / 2)
    70          return last_char;
    71
    72  /* -------------------------------------------------------------------- */
    73  /*      Move the existing data to the start of the buffer.              */
    74  /* -------------------------------------------------------------------- */
    75      memmove(state->buffer, last_char, char_remaining);
    76      state->buffer_filled = (int)char_remaining;
    77      last_char = state->buffer;
    78
    79  /* -------------------------------------------------------------------- */
    80  /*      Refill.                                                         */
    81  /* -------------------------------------------------------------------- */
    82      char_requested = sizeof(state->buffer) - state->buffer_filled - 1;
    83      bytes_read = pj_ctx_fread( state->ctx, state->buffer + state->buffer_filled,
    84                                 1, char_requested, state->fid );
    85      if (bytes_read < char_requested)
    86      {
    87          state->at_eof = 1;
    88          state->buffer[state->buffer_filled + bytes_read] = '\0';
    89      }
    90
    91  /* -------------------------------------------------------------------- */
    92  /*      Line continuations: skip whitespace after escaped newlines      */
    93  /* -------------------------------------------------------------------- */
    94      r = state->buffer;
    95      w = state->buffer;
    96      while (*r) {
    97          /* Escaped newline? */
    98          while ((r[0]=='\\')  &&  ((r[1]=='\n') || (r[1]=='\r'))) {
    99              r += 2;
   100              while (isspace (*r))
   101                  r++;
   102              /* we also skip comments immediately after an escaped newline */
   103              while (*r=='#') {
   104                  while( *r && (*r != '\n') )
   105                      r++;
   106                  while (isspace (*r))
   107                      r++;
   108                  /* Reaching end of buffer while skipping continuation comment is currently an error */
   109                  if (0==*r) {
   110                      pj_ctx_set_errno (state->ctx, -2);
   111                      pj_log (state->ctx, PJ_LOG_ERROR, "init file too big");
   112                      return 0;
   113                  }
   114              }
   115          }
   116          *w++ = *r++;
   117      }
   118      *w = 0;
   119      state->buffer_filled += (int)(bytes_read - (r-w));
   120
   121      return last_char;
   122  }
