   124  /************************************************************************/
   125  /*                              get_opt()                               */
   126  /************************************************************************/
   127  static paralist *
   128  get_opt(projCtx ctx, paralist **start, PAFile fid, char *name, paralist *next,
   129          int *found_def) {
   130      pj_read_state *state = (pj_read_state*) calloc(1,sizeof(pj_read_state));
   131      char sword[MAX_CR_ESCAPE];
   132      char *pipeline;
   133      int len;
   134      int in_target = 0;
   135      const char *next_char = NULL;
   136      state->fid = fid;
   137      state->ctx = ctx;
   138      next_char = fill_buffer(state, NULL);
   139      if(found_def)
   140          *found_def = 0;
   141
   142      len = (int)strlen(name);
   143      *sword = 't';
   144
   145      if (0==next_char)
   146          return 0;
   147
   148      /* loop till we find our target keyword */
   149      while (*next_char)
   150      {
   151          next_char = fill_buffer(state, next_char);
   152
   153          /* Skip white space. */
   154          while( isspace(*next_char) )
   155              next_char++;
   156
   157          next_char = fill_buffer(state, next_char);
   158          if (0==next_char)
   159              return 0;
   160
   161          /* for comments, skip past end of line. */
   162          if( *next_char == '#' )
   163          {
   164              while( *next_char && *next_char != '\n' )
   165                  next_char++;
   166
   167              next_char = fill_buffer(state, next_char);
   168              if (0==next_char)
   169                  return 0;
   170              if (*next_char == '\n')
   171                  next_char++;
   172              if (*next_char == '\r')
   173                  next_char++;
   174
   175          }
   176
   177          /* Is this our target? */
   178          else if( *next_char == '<' )
   179          {
   180              /* terminate processing target on the next block definition */
   181              if (in_target)
   182                  break;
   183
   184              next_char++;
   185              if (strncmp(name, next_char, len) == 0
   186                  && next_char[len] == '>')
   187              {
   188                  /* skip past target word */
   189                  next_char += len + 1;
   190                  in_target = 1;
   191                  if(found_def)
   192                      *found_def = 1;
   193              }
   194              else
   195              {
   196                  /* skip past end of line */
   197                  while( *next_char && *next_char != '\n' )
   198                      next_char++;
   199              }
   200          }
   201          else if (in_target)
   202          {
   203              const char *start_of_word = next_char;
   204              int word_len = 0;
   205
   206              if (*start_of_word == '+')
   207              {
   208                  start_of_word++;
   209                  next_char++;
   210              }
   211
   212              /* capture parameter */
   213              while ( *next_char && !isspace(*next_char) )
   214              {
   215                  next_char++;
   216                  word_len++;
   217              }
   218
   219              strncpy(sword+1, start_of_word, word_len);
   220              sword[word_len+1] = '\0';
   221
   222              /* do not override existing parameter value of same name - unless in pipeline definition */
   223              pipeline = pj_param(ctx, *start, "sproj").s;
   224              if (pipeline && strcmp (pipeline, "pipeline"))
   225                  pipeline = 0;
   226              if (pipeline || !pj_param(ctx, *start, sword).i) {
   227                  /* don't default ellipse if datum, ellps or any earth model
   228                     information is set. */
   229                  if( strncmp(sword+1,"ellps=",6) != 0
   230                      || (!pj_param(ctx, *start, "tdatum").i
   231                          && !pj_param(ctx, *start, "tellps").i
   232                          && !pj_param(ctx, *start, "ta").i
   233                          && !pj_param(ctx, *start, "tb").i
   234                          && !pj_param(ctx, *start, "trf").i
   235                          && !pj_param(ctx, *start, "tf").i) )
   236                  {
   237                      next = next->next = pj_mkparam(sword+1);
   238                  }
   239                  else
   240                      next = next->next = pj_mkparam(sword+1);
   241              }
   242          }
   243          else
   244          {
   245              /* skip past word */
   246              while( *next_char && !isspace(*next_char) ) {
   247                  next_char++;
   248              }
   249
   250          }
   251      }
   252
   253      if (errno == 25)
   254          errno = 0;
   255
   256      free(state);
   257      return next;
   258  }
