   306      /*
   307      ** Otherwise we try to open the file and search for it.
   308      */
   309      if ((opt = strrchr(fname, ':')) != NULL)
   310          *opt++ = '\0';
   311      else { pj_ctx_set_errno(ctx,-3); return NULL; }
   312
   313      if ( (fid = pj_open_lib(ctx,fname, "rt")) != NULL)
   314          next = get_opt(ctx, start, fid, opt, next, found_def);
   315      else
   316          return NULL;
   317
   318      pj_ctx_fclose(ctx, fid);
   319      if (errno == 25)
   320          errno = 0; /* unknown problem with some sys errno<-25 */
   321
   322      /*
   323      ** If we seem to have gotten a result, insert it into the
   324      ** init file cache.
   325      */
   326      if( next != NULL && next != orig_next )
   327          pj_insert_initcache( name, orig_next->next );
   328
   329      return next;
   330  }
   331
   332  paralist * pj_get_init(projCtx ctx, paralist **start, paralist *next, char *name, int *found_def) {
   333      return get_init(ctx, start, next, name, found_def);
   334  }
