   336  /************************************************************************/
   337  /*                            pj_init_plus()                            */
   338  /*                                                                      */
   339  /*      Same as pj_init() except it takes one argument string with      */
   340  /*      individual arguments preceded by '+', such as "+proj=utm       */
   341  /*      +zone=11 +ellps=WGS84".                                         */
   342  /************************************************************************/
   343
   344  PJ *
   345  pj_init_plus( const char *definition )
   346
   347  {
   348      return pj_init_plus_ctx( pj_get_default_ctx(), definition );
   349  }
   350
   351  PJ *
   352  pj_init_plus_ctx( projCtx ctx, const char *definition )
   353  {
   354  #define MAX_ARG 200
   355      char        *argv[MAX_ARG];
   356      char        *defn_copy;
   357      int         argc = 0, i, blank_count = 0;
   358      PJ      *result = NULL;
   359
   360      /* make a copy that we can manipulate */
   361      defn_copy = (char *) pj_malloc( strlen(definition)+1 );
   362      strcpy( defn_copy, definition );
   363
   364      /* split into arguments based on '+' and trim white space */
   365
   366      for( i = 0; defn_copy[i] != '\0'; i++ )
   367      {
   368          switch( defn_copy[i] )
   369          {
   370            case '+':
   371              if( i == 0 || defn_copy[i-1] == '\0' || blank_count > 0 )
   372              {
   373                  /* trim trailing spaces from the previous param */
   374                  if( blank_count > 0 )
   375                  {
   376                      defn_copy[i - blank_count] = '\0';
   377                      blank_count = 0;
   378                  }
   379
   380                  if( argc+1 == MAX_ARG )
   381                  {
   382                      pj_ctx_set_errno( ctx, -44 );
   383                      goto bum_call;
   384                  }
   385
   386                  argv[argc++] = defn_copy + i + 1;
   387              }
   388              break;
   389
   390            case ' ':
   391            case '\t':
   392            case '\n':
   393              /* trim leading spaces from the current param */
   394              if( i == 0 || defn_copy[i-1] == '\0' || argc == 0 || argv[argc-1] == defn_copy + i )
   395                  defn_copy[i] = '\0';
   396              else
   397                  blank_count++;
   398              break;
   399
   400            default:
   401              /* reset blank_count */
   402              blank_count = 0;
   403          }
   404      }
   405      /* trim trailing spaces from the last param */
   406      defn_copy[i - blank_count] = '\0';
   407
   408      /* perform actual initialization */
   409      result = pj_init_ctx( ctx, argc, argv );
   410
   411  bum_call:
   412      pj_dalloc( defn_copy );
   413
   414      return result;
   415  }
